Translate("frFR", "feralas", {
	title = "Féralas",
	sections = {
		{
			title = "Résumé",
			text = [=[Féralas est la grande étendue sauvage et verte du sud-ouest de {link:kalimdor}Kalimdor{/link}. Ses forêts sont hautes et humides, ses rivières larges, et deux immenses piliers de pierre, les {link:the-twin-colossals}Colosses jumeaux{/link}, se dressent au-dessus de ses collines du nord. Des géants arpentent ces collines du nord. Des hippogriffes nichent sur ses hauteurs du sud, et des dragons féeriques voltigent dans ses clairières. Sous les arbres gisent les ruines d'un âge ancien, et au cœur de la forêt se dressent les salles brisées d'Eldre'Thalas, la cité des {red:highborne}Bien-nés{/red} que l'on nomme aujourd'hui {red:dire-maul}Hache-tripes{/red}. C'est l'un des derniers lieux sauvages de Kalimdor, et l'{link:alliance}Alliance{/link} comme la {link:horde}Horde{/link} sont venues le revendiquer.]=],
		},
		{
			title = "Origines",
			text = [=[Il y a longtemps, cette forêt appartenait aux {link:night-elves}elfes de la nuit{/link}. Leurs pavillons, leurs tours et leurs sanctuaires se dressent encore en ruine d'un bout à l'autre, des {link:ruins-of-solarsal}Ruines de Solarsal{/link} sur la côte aux pierres tombées des Plateaux sauvages. La plus grande de leurs œuvres était Eldre'Thalas. Elle survécut à la {link:great-sundering}Grande Fracture{/link}, mais son prince, {red:tortheldrin}Tortheldrin{/red}, nourrit la soif de magie de son peuple avec des puissances toujours plus sombres. Certains de ses sujets se dressèrent contre lui. Ils furent vaincus et s'enfuirent vers l'ouest, par-delà la mer, et leurs descendants sont les {link:skyborne}Skyborne{/link} de {link:zephras-isle}Zephras Isle{/link}. La cité qui resta sombra lentement dans la ruine. Nulle chronique ne rapporte quand les derniers kaldorei quittèrent le reste de Féralas, ni pourquoi.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Après la {link:third-war}Troisième Guerre{/link}, la générale {link:shandris-feathermoon}Shandris Feathermoon{/link} mena une expédition des {link:sentinels}Sentinelles{/link} en Féralas et fit du {link:feathermoon-stronghold}Bastion de Feathermoon{/link}, sur une île au large de la côte ouest, son siège. Son dessein est clair. L'armée des Sentinelles contient la {link:horde}Horde{/link} en {link:ashenvale}Orneval{/link} et dans les {link:stonetalon-mountains}Serres-Rocheuses{/link}, et elle ne laissera pas la Horde prendre les dernières terres sauvages derrière elles. La Horde est venue malgré tout. Des taurens, des orcs et des trolls tiennent le camp {link:camp-mojache}Mojache{/link} à l'est, entre les ogres au nord et les gnolls au sud.

Aucun des deux camps n'est le seul ennemi de ces terres. Les ogres gordunni balafrent la forêt partout où ils s'installent. Les {link:naga}nagas{/link} Hatecrest fouillent les ruines côtières en quête d'une chose que nul ne comprend. Les taurens Totem sinistre capturent des dragons féeriques, et les gnolls Griffebois sont chaque saison plus désespérés. Leur désespoir a une cause. Au sud-est, en un lieu nommé le {link:the-writhing-deep}Gouffre grouillant{/link}, des insectes venus de {link:silithus}Silithus{/link} ont bâti une ruche, et ils se répandent.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les {link:sentinels}Sentinelles{/link} de {link:feathermoon-stronghold}Feathermoon{/link}.{/b} Guerrières, druides, prêtresses et érudits elfes de la nuit sous les ordres de {link:shandris-feathermoon}Shandris Feathermoon{/link}.
• {b}La {link:horde}Horde{/link} du camp {link:camp-mojache}Mojache{/link}.{/b} Chasseurs taurens, guerriers orcs et féticheurs trolls, qui tiennent la forêt de l'est.
• {b}Les ogres gordunni.{/b} Une tribu qui tient les terres au nord du camp Mojache et les ruines des Plateaux sauvages.
• {b}Les nagas Hatecrest.{/b} Le peuple-serpent de la côte ouest, de l'{link:isle-of-dread}Île de l'effroi{/link} et des {link:ruins-of-solarsal}Ruines de Solarsal{/link}.
• {b}Les harpies Northspring.{/b} Elles nichent dans les {link:ruins-of-ravenwind}Ruines de Vent-du-Corbeau{/link}, au nord-ouest.
• {b}Les gnolls Griffebois.{/b} Leurs camps emplissent les collines au sud du camp Mojache.
• {b}Les {link:grimtotem-clan}Totem sinistre{/link}.{/b} Des taurens qui rejettent {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, campés dans la forêt de l'est.
• {b}Les Zukk'ash.{/b} Des insectes de l'espèce silithide, dans le {link:the-writhing-deep}Gouffre grouillant{/link}.
• {b}Les créatures sauvages.{/b} Géants des montagnes, tréants, hippogriffes, fées-dragons, yétis, singes groddocs et ours fourrure-de-fer.
• {b}Les draconiens verts.{/b} Gardiens du {link:dream-bough}Bosquet du rêve{/link} au nord, porte du {link:emerald-dream}Rêve d'émeraude{/link}.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}L'âge des elfes.{/b} Les elfes de la nuit et les Bien-nés bâtirent dans toute la forêt. Eldre'Thalas en était la couronne.
• {b}La rébellion d'Eldre'Thalas.{/b} Après la guerre des Anciens, des rebelles se soulevèrent contre le prince Tortheldrin et s'enfuirent dans le ciel. Le prince garda sa cité.
• {b}Le long silence.{/b} Pendant des âges, la forêt fut laissée aux bêtes, aux ogres et à la ruine.
• {b}La venue des {link:sentinels}Sentinelles{/link}.{/b} Après la {link:third-war}Troisième Guerre{/link}, {link:shandris-feathermoon}Shandris Feathermoon{/link} mena son expédition vers le sud et fit du {link:feathermoon-stronghold}Bastion de Feathermoon{/link} son rempart.
• {b}Le temps présent.{/b} La {link:horde}Horde{/link} tient le camp {link:camp-mojache}Mojache{/link}. {link:naga}Nagas{/link}, ogres, harpies et gnolls pressent de tous côtés, et une ruche d'insectes grandit au sud.]=],
		},
		{
			title = "Légendes des terres sauvages",
			text = [=[• Les trolls du camp {link:camp-mojache}Mojache{/link} disent qu'une bête tuée par la violence laisse derrière elle son muisek, un esprit qui peut s'échapper et revenir sous une forme plus grande et plus vengeresse.
• Les érudits venus de {link:thousand-needles}Mille pointes{/link} remarquent que le vert de Féralas s'arrête aux canyons aussi net qu'un trait tiré.
• Un livre intitulé {i}Féralas : une histoire{/i} est conservé par une gardienne du savoir de {link:rut-theran-village}Rut'theran{/link}, au pied de {link:teldrassil}Teldrassil{/link}. Selon elle, tout ce qui avait vraiment de la valeur dans les ruines fut emporté il y a longtemps par les ogres et les harpies.
• Un ingénieur gobelin de la {link:the-forgotten-coast}Côte oubliée{/link} dit que c'est le pire endroit du monde pour ouvrir une boutique.]=],
		},
	},
})

Translate("frFR", "feathermoon-stronghold", {
	title = "Bastion de Feathermoon",
	aliases = { "Feathermoon" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Bastion de Feathermoon se dresse sur l'Île de Sardor, au large de la côte ouest de {link:feralas}Féralas{/link}. C'est le siège de la générale {link:shandris-feathermoon}Shandris Feathermoon{/link} et le rempart méridional des {link:sentinels}Sentinelles{/link}. Ses murs abritent des guerrières et des archères, un druide dans une maison perchée dans un arbre, une prêtresse érudite, deux spécialistes des ruines, ainsi que les travailleurs du cuir et les marchands qui nourrissent et équipent la garnison. Des hippogriffes emportent ses voyageurs à travers {link:kalimdor}Kalimdor{/link}. Le bastion est puissant, mais il n'est pas facile à tenir : des nagas ont pris les ruines au sud de la même île, et la {link:horde}Horde{/link} n'est jamais loin. Un exemplaire de {red:the-sentinels-and-the-long-vigil}The Sentinels and the Long Vigil{/red} y est conservé.]=],
		},
	},
})

Translate("frFR", "ruins-of-solarsal", {
	title = "Ruines de Solarsal",
	aliases = { "Solarsal" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Ruines de Solarsal se trouvent à l'extrémité sud de l'Île de Sardor, à courte marche du {link:feathermoon-stronghold}Bastion de Feathermoon{/link}. Elles sont plus anciennes que toute mémoire vivante. Les {link:sentinels}Sentinelles{/link} les fouillèrent à leur arrivée, n'y trouvèrent rien et les laissèrent en paix. Puis les nagas Hatecrest vinrent en grand nombre. Au cœur des ruines se dresse une gloriette visiblement plus récente que les pierres qui l'entourent. Ses flancs portent une rangée de glyphes répétés qu'aucun érudit ne sait lire, et sa pierre est tiède au toucher.]=],
		},
	},
})

Translate("frFR", "isle-of-dread", {
	title = "Île de l'effroi",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Île de l'effroi s'étend de l'autre côté de l'eau, au sud de l'Île de Sardor. Les nagas Hatecrest tiennent ses rivages, et dans une grotte au sud de l'île, ils ont creusé. De ces fouilles, leur seigneur {link:lord-shalzaru}Shalzaru{/link} a tiré une étrange relique que les érudits de {link:feathermoon-stronghold}Feathermoon{/link} n'ont pu identifier. Plus au sud encore, l'île appartient aux chimérocs, de grandes bêtes qui parcourent le sud de l'île, et à un monstrueux seigneur de leur espèce nommé Lakmaeran.]=],
		},
	},
})

Translate("frFR", "the-forgotten-coast", {
	title = "La Côte oubliée",
	aliases = { "Côte oubliée" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Côte oubliée est le long rivage occidental de {link:feralas}Féralas{/link}, face à {link:feathermoon-stronghold}Feathermoon{/link} de l'autre côté du détroit. Ses plages sont sauvages et ses eaux agitées. Des élémentaires de la mer surgissent du ressac, et ils ont brisé plus d'une barque qui tentait de longer la côte. Un unique quai se dresse sur ce rivage. Un gobelin du {link:steamwheedle-cartel}Cartel Gentepression{/link} y a installé son atelier d'ingénierie, contre tout bon sens, et un robot {link:gnomes}gnome{/link} égaré y fut un jour conduit pour attendre les secours.]=],
		},
	},
})

Translate("frFR", "camp-mojache", {
	title = "Camp Mojache",
	aliases = { "Mojache" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le camp Mojache est la tête de pont de la {link:horde}Horde{/link} en {link:feralas}Féralas{/link}, un camp dans la forêt de l'est. {link:tauren}Taurens{/link}, orcs et trolls y vivent côte à côte. Le camp est pressé de deux côtés. Les ogres gordunni tiennent les terres du fleuve au nord, et les gnolls Griffebois lancent leurs raids depuis les collines du sud, plus férocement à chaque saison. Ses guerriers tiennent la ligne, ses chasseurs pistent la forêt, son féticheur accomplit d'étranges rites, et ses travailleurs du cuir paient bien les peaux de yéti. Des coursiers du vent le relient au reste de la Horde.]=],
		},
	},
})

Translate("frFR", "thalanaar", {
	title = "Thalanaar",
	sections = {
		{
			title = "Résumé",
			text = [=[Thalanaar est un petit relais des elfes de la nuit à l'extrême sud-est de {link:feralas}Féralas{/link}, là où la forêt s'arrête au bord de {link:thousand-needles}Mille pointes{/link}. Des coursiers de {link:feathermoon-stronghold}Feathermoon{/link} y portent ses provisions à travers toute la largeur de la forêt, une longue route qui traverse les terres de la {link:horde}Horde{/link}, des gnolls et de pire encore. Le druide {link:falfindel-waywarder}Falfindel Waywarder{/link} le tient, et un maître des hippogriffes et une travailleuse du cuir de l'ancien art tribal vivent à ses côtés.]=],
		},
	},
})

Translate("frFR", "the-twin-colossals", {
	title = "Les Colosses jumeaux",
	aliases = { "Colosses jumeaux" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Colosses jumeaux sont deux immenses piliers de roche au nord de {link:feralas}Féralas{/link}, le Pilier Est et le Pilier Ouest. Des géants des montagnes arpentent les terres pierreuses à leur pied, et le sol tremble sur leur passage. Une femme qui vit près des piliers peut envoyer un voyageur au sommet de l'un d'eux, mais elle prévient qu'elle ne peut ramener personne en bas. Un géant nommé {link:rockbiter}Rockbiter{/link} a établi son camp à leur ombre.]=],
		},
	},
})

Translate("frFR", "ruins-of-ravenwind", {
	title = "Ruines de Vent-du-Corbeau",
	aliases = { "Vent-du-Corbeau" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Ruines de Vent-du-Corbeau se trouvent au nord-ouest de {link:feralas}Féralas{/link}, sur le continent, à l'ouest du {link:dream-bough}Bosquet du rêve{/link}. Les harpies Northspring y nichent aujourd'hui, et près des pierres Hatetalon, au nord des ruines, on peut appeler leur reine. Des choses plus anciennes demeurent. Quatre flammes brûlent encore parmi les pierres, nommées Samha, Imbel, Byltan et Lahassa, et entre elles se dresse le monolithe d'Equinex, une pierre scellée qui ne s'ouvre qu'à un bâton chargé de leur feu. Quelque chose y était caché.]=],
		},
	},
})

Translate("frFR", "dream-bough", {
	title = "Bosquet du rêve",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Bosquet du rêve est un grand arbre sur une île du Lac Jademir, à l'extrême nord de {link:feralas}Féralas{/link}. C'est l'une des portes du {link:emerald-dream}Rêve d'émeraude{/link}. Ses gardiens sont des draconiens du vol vert : oracles, gardiens des arbres et gardes-rameaux qui ne laissent personne approcher, et au-dessus d'eux de grands dragons verts comme {link:lethlas}Lethlas{/link} et Dreamroarer. La terre qui entoure le lac se nomme Oneiros.]=],
		},
	},
})

Translate("frFR", "rage-scar-hold", {
	title = "Repaire des Griffes féroces",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Repaire des Griffes féroces se trouve dans la forêt du nord de {link:feralas}Féralas{/link}. C'est le domaine des yétis les plus féroces de la forêt. Les anciens des Griffes féroces sont plus grands et plus sauvages que leurs cousins du sud-ouest, et leurs peaux sont plus épaisses. Les travailleurs du cuir de {link:feathermoon-stronghold}Feathermoon{/link} comme du camp {link:camp-mojache}Mojache{/link} croient que de telles peaux, bien tannées, peuvent être plus dures que le fer, et ils paient bien toutes celles qui leur parviennent.]=],
		},
	},
})

Translate("frFR", "feral-scar-vale", {
	title = "Val des Griffes farouches",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Val des Griffes farouches est une vallée à l'ouest du camp {link:camp-mojache}Mojache{/link}, et le premier foyer des yétis de {link:feralas}Féralas{/link}. Les bêtes y sont nombreuses, et les chasseurs des deux factions traquent leurs épaisses peaux. Dans une grotte près du val, un robot {link:gnomes}gnome{/link} à tête chercheuse gisait autrefois, écrasé et brisé, jusqu'à ce qu'un voyageur réponde à l'appel de son créateur et le conduise jusqu'à la côte.]=],
		},
	},
})

Translate("frFR", "gordunni-outpost", {
	title = "Avant-poste des Gordunni",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Avant-poste des Gordunni se trouve en amont du fleuve, au nord du camp {link:camp-mojache}Mojache{/link}. C'est la place forte la plus proche des ogres gordunni, et les terres alentour portent la marque de leur passage : arbres abattus et sol souillé. Les ogres y enfouissent un minerai à la lueur bleue, le cobalt gordunni, et le gardent farouchement. Des parchemins souillés trouvés dans l'avant-poste décrivent une cérémonie menée par les seigneurs-mages de la tribu.]=],
		},
	},
})

Translate("frFR", "high-wilderness", {
	title = "Les plateaux sauvages",
	aliases = { "Ruines d'Isildien", "Isildien" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Plateaux sauvages sont les hautes terres au sud-ouest du camp {link:camp-mojache}Mojache{/link}. Ils appartenaient autrefois aux elfes de la nuit, et leurs tours s'y dressent encore, brisées et abandonnées, parmi les Ruines d'Isildien. Les Gordunni s'en sont emparés. Leurs chamans et leurs démonistes pratiquent leur magie parmi les pierres, et les arbres alentour dépérissent. Les ogres des Plateaux sauvages sont plus forts que ceux de l'avant-poste du nord, et les seigneurs-mages de la tribu s'y rassemblent.]=],
		},
	},
})

Translate("frFR", "frayfeather-highlands", {
	title = "Hautes-terres des Aigreplumes",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Hautes-terres des Aigreplumes s'élèvent au sud de {link:feralas}Féralas{/link}, à côté des Plateaux sauvages. Elles doivent leur nom aux hippogriffes sauvages qui y nichent, des jeunes cerfailes aux vieux patriarches. L'hippogriffe est depuis longtemps un ami des elfes de la nuit, loyal et fidèle, et c'est pourquoi les trolls du camp {link:camp-mojache}Mojache{/link} chassent ces bêtes sauvages pour la force de leur esprit.]=],
		},
	},
})

Translate("frFR", "grimtotem-compound", {
	title = "Base des Totem sinistre",
	sections = {
		{
			title = "Résumé",
			text = [=[La Base des Totem sinistre est un camp des taurens {link:grimtotem-clan}Totem sinistre{/link} dans la forêt de l'est, à l'ouest du camp {link:camp-mojache}Mojache{/link}. Ses naturalistes, ses pillards et ses chamans capturent des fées-dragons, les dragons féeriques de {link:feralas}Féralas{/link}, et les gardent enfermés dans des cages de bambou. Nul ne sait ce qu'ils en veulent. Deux elfes de la nuit surveillent la base depuis la crête qui la domine, et la {link:horde}Horde{/link} de Mojache, quand elle apprit que les Totem sinistre étaient là, mit leurs cornes à prix.]=],
		},
	},
})

Translate("frFR", "lariss-pavilion", {
	title = "Pavillon de Lariss",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Pavillon de Lariss est une ruine elfique à l'est de {link:feralas}Féralas{/link}, au nord du camp {link:camp-mojache}Mojache{/link}. Ses vieilles pierres sont devenues le refuge d'{link:azj-tordin}Azj'Tordin{/link}, un ancien qui a fui Eldre'Thalas et son prince déchu. Il y vit discrètement, et il ne lui reste guère de son ancienne vie que son savoir.]=],
		},
	},
})

Translate("frFR", "woodpaw-hills", {
	title = "Collines des Griffebois",
	aliases = { "Tanière des Griffebois" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Collines des Griffebois s'étendent au sud du camp {link:camp-mojache}Mojache{/link}, et les gnolls de la meute Griffebois les emplissent de camps et de tanières. Pendant des années, leurs raids contre le camp ne furent qu'une nuisance. Depuis peu, ils sont devenus frénétiques. Leurs propres plans de bataille en montrent la raison : l'essentiel de leurs forces est tourné vers le sud, contre les insectes du {link:the-writhing-deep}Gouffre grouillant{/link}, et ils perdent. Une guerre sur deux fronts les a rendus désespérés.]=],
		},
	},
})

Translate("frFR", "the-writhing-deep", {
	title = "Gouffre grouillant",
	aliases = { "Le Gouffre grouillant" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Gouffre grouillant est une ruche à l'extrême sud-est de {link:feralas}Féralas{/link}. Son sol est tordu en monticules et en tunnels, et il grouille de Zukk'ash : dards, guêpes, ouvriers et fouisseurs. Les érudits de {link:darnassus}Darnassus{/link} comme ceux d'{link:orgrimmar}Orgrimmar{/link} les nomment silithides, parents des essaims de {link:silithus}Silithus{/link}. Ils scellent leurs captifs vivants dans des cocons de bave durcie. Un géant parmi eux, nommé {link:stinglasher}Stinglasher{/link}, parcourt la ruche enveloppé d'une aura que ses congénères plus faibles ne partagent pas.]=],
		},
	},
})

Translate("frFR", "shandris-feathermoon", {
	title = "Shandris Feathermoon",
	subtitle = "Générale de l'armée des Sentinelles",
	found = "Bastion de Feathermoon, dans l'enceinte principale",
	hint = [=[Cherchez la générale des Sentinelles dans son bastion insulaire, au large de la côte ouest.]=],
	allegiance = "Sentinelles · Darnassus",
	aliases = { "Shandris", "générale Feathermoon" },
	sections = {
		{
			title = "Résumé",
			text = [=[Shandris Feathermoon est la générale de l'armée des {link:sentinels}Sentinelles{/link}, l'épée de {link:tyrande-whisperwind}Tyrande Whisperwind{/link} et le premier soldat des {link:night-elves}elfes de la nuit{/link}. Elle ne commande pas depuis {link:darnassus}Darnassus{/link}. Elle a établi son siège au {link:feathermoon-stronghold}Bastion de Feathermoon{/link}, sur une île au large de {link:feralas}Féralas{/link}, à la limite sud des terres que son peuple garde encore. Sa voix est vive, ses mots sont rares, et ceux qui la servent bien sont remerciés, payés, puis renvoyés sur le terrain.]=],
		},
		{
			title = "Importance",
			text = [=[Les {link:sentinels}Sentinelles{/link} sont l'armée d'un peuple qui ne devait jamais en avoir besoin en cet âge. Depuis la {link:third-war}Troisième Guerre{/link}, elles combattent la {link:horde}Horde{/link} en {link:ashenvale}Orneval{/link} et dans les {link:stonetalon-mountains}Serres-Rocheuses{/link}, et Shandris tient cette ligne à travers tout {link:kalimdor}Kalimdor{/link}. {link:feralas}Féralas{/link} est sa réponse à une question plus vaste : que restera-t-il du monde sauvage quand la guerre prendra fin ? Elle est venue au sud pour garder les dernières terres vertes du continent hors des mains de la Horde, et elle entend bien les garder.

Son histoire remonte plus loin que toutes les guerres du présent. On raconte qu'elle était enfant quand la {link:war-of-the-ancients}guerre des Anciens{/link} brisa son monde, une orpheline que la jeune prêtresse {link:tyrande-whisperwind}Tyrande{/link} prit sous sa protection.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle mena l'expédition des {link:sentinels}Sentinelles{/link} en {link:feralas}Féralas{/link} et bâtit le {link:feathermoon-stronghold}Bastion de Feathermoon{/link}.
• Elle envoya des éclaireurs dans les {link:ruins-of-solarsal}Ruines de Solarsal{/link} quand les nagas Hatecrest s'y rassemblèrent, et confia la campagne contre les nagas à son second, {link:latronicus-moonspear}Latronicus Moonspear{/link}.
• Elle a refusé de jeter toutes ses forces contre les nagas, de peur de laisser le bastion ouvert à la {link:horde}Horde{/link}, ou à pire encore.
• Elle fit parvenir la nouvelle de la ruche des Zukk'ash à {link:darnassus}Darnassus{/link}, et une copie du rapport du coursier {link:raschal-the-courier}Raschal{/link} à la prêtresse Gracina Spiritmight, du {link:temple-of-the-moon}Temple de la Lune{/link}.
• Le druide {link:quintis-jonespyre}Quintis Jonespyre{/link} la nomme, avec le Protectorat, parmi les collègues qui s'interrogent sur l'appétit de l'archidruide pour le grain-du-matin.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique écrite à ce jour ne dit quand Shandris fut nommée générale, ni ce qu'elle fit durant la {link:third-war}Troisième Guerre{/link} elle-même. Les récits de son enfance viennent des histoires de la guerre des Anciens, non de sa propre bouche.]=],
		},
	},
	chapters = {
		{
			title = "La pierre tiède",
			hint = "Fouillez les vieilles ruines au sud de l'île de la générale.",
			text = [=[Shandris avait cru les {link:ruins-of-solarsal}Ruines de Solarsal{/link} vides. Quand les nagas y vinrent en nombre, elle y vit d'abord le début d'une attaque, sans en être certaine. Le rapport qui lui revint décrivait une gloriette plus récente que les ruines, des glyphes que nul ne savait lire et une pierre tiède sous la main. Elle jugea la chose troublante. Quel que fût le dessein des nagas, elle savait désormais qu'ils comptaient rester.]=],
		},
		{
			title = "Contre les Hatecrest",
			hint = "Répondez à l'appel de la générale contre les nagas.",
			text = [=[Shandris pesa l'affaire comme le doit une générale. Elle voulait frapper les nagas avec toutes les lames dont elle disposait. Elle savait aussi ce qu'un bastion vide inviterait. Finalement, elle confia la tâche à {link:latronicus-moonspear}Latronicus{/link}, qui observait les nagas depuis le plus longtemps, et garda les yeux sur la guerre au sens large.]=],
		},
		{
			title = "L'essor des silithides",
			hint = [=[Recevez les remerciements de la générale pour le sauvetage du coursier.]=],
			text = [=[Quand {link:raschal-the-courier}Raschal{/link} revint vivant du {link:the-writhing-deep}Gouffre grouillant{/link}, Shandris remercia elle-même ses sauveteurs. Puis elle se tourna aussitôt vers son rapport. Des insectes qui scellent des elfes vivants dans des cocons n'étaient pas l'affaire d'un seul bastion. Elle envoya le rapport à {link:darnassus}Darnassus{/link} et une copie à une prêtresse qui connaissait de telles créatures, et demanda à Elune de veiller sur eux tous.]=],
		},
	},
	mentions = {
		{ text = "Les {link:ruins-of-solarsal}Ruines de Solarsal{/link}" },
		{
			text = [=[Retour au {link:feathermoon-stronghold}Bastion de Feathermoon{/link}]=],
		},
		{ text = "Contre les Hatecrest" },
		{ text = "L'accueil d'un héros" },
		{ text = "L'essor des silithides" },
		{ text = "La requête de Jonespyre, qui la nomme parmi le Protectorat" },
	},
	bonds = {
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "sa grande prêtresse" },
		{ id = "latronicus-moonspear", name = "Latronicus Moonspear", note = "son second" },
		{ id = "ginro-hearthkindle", name = "Ginro Hearthkindle", note = "a cherché son coursier disparu" },
		{ id = "quintis-jonespyre", name = "Quintis Jonespyre", note = "son collègue du Protectorat" },
		{ id = "raschal-the-courier", name = "Raschal le coursier", note = "son coursier" },
		{ id = "hadoken-swiftstrider", name = "Hadoken Swiftstrider", note = "tient le camp de la Horde à l'est" },
	},
})

Translate("frFR", "latronicus-moonspear", {
	title = "Latronicus Moonspear",
	subtitle = "Second de Feathermoon",
	found = "Bastion de Feathermoon, aux côtés de la générale",
	hint = [=[Parlez à l'officier qui se tient aux côtés de la générale à Feathermoon.]=],
	allegiance = "Sentinelles · Bastion de Feathermoon",
	aliases = { "Latronicus", "Latro" },
	sections = {
		{
			title = "Résumé",
			text = [=[Latronicus Moonspear est le commandant en second du {link:feathermoon-stronghold}Bastion de Feathermoon{/link}, et l'officier qui observe les nagas Hatecrest depuis le plus longtemps. C'est un soldat pragmatique. Il apprécie ceux qui obtiennent des résultats, paie ses primes sur le trésor du bastion sans se plaindre, et admet volontiers que les énigmes des vieilles reliques le dépassent. Celles-là, il les confie à sa femme.]=],
		},
		{
			title = "Importance",
			text = [=[Là où {link:shandris-feathermoon}Shandris{/link} pense à la guerre tout entière, Latronicus pense à l'île. Sa campagne contre les nagas est une petite guerre à part entière, livrée pour l'Île de Sardor et les eaux qui l'entourent. Il garde aussi un œil méfiant sur le mauvais usage de la magie, et dit des elfes qui s'en croient les maîtres qu'ils sont les esclaves de leur propre faim.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mène la lutte contre les nagas Hatecrest sur l'Île de Sardor et l'{link:isle-of-dread}Île de l'effroi{/link}.
• Il apprit de ses éclaireurs que les nagas étaient menés par des membres de leur noblesse, et désigna le seigneur {link:lord-shalzaru}Shalzaru{/link} pour la mort.
• Il déclara le coursier {link:raschal-the-courier}Raschal{/link} disparu et envoya des chercheurs auprès de {link:ginro-hearthkindle}Ginro Hearthkindle{/link}.
• Il veut que la toile de la mage Lethtendris soit rapportée de {red:dire-maul}Hache-tripes{/red}, afin que la magie qui y est prise puisse être rendue au monde sauvage.]=],
		},
	},
	chapters = {
		{
			title = "La noblesse naga",
			hint = [=[Brisez l'emprise des nagas sur les îles proches de Feathermoon.]=],
			text = [=[Latronicus mena sa guerre en deux temps : affaiblir les nagas dans leur nombre et dans leur commandement, et découvrir ce qu'ils cherchaient en creusant. Les écailles d'abord. Puis ses éclaireurs nommèrent un cruel seigneur {link:naga}naga{/link}, {link:lord-shalzaru}Shalzaru{/link}, qui avait tiré une étrange relique d'une grotte de l'{link:isle-of-dread}Île de l'effroi{/link}. Quand Shalzaru tomba, Latronicus crut que les nagas resteraient longtemps dans la confusion. La relique, il ne sut pas du tout la lire.]=],
		},
		{
			title = "La relique",
			hint = "Portez la relique naga à l'érudite de Feathermoon.",
			text = [=[Il demanda que la relique soit portée à sa femme, {link:vestia-moonspear}Vestia{/link}, qu'il dit être la meilleure érudite de tous les pays. Il avait besoin de savoir ce que c'était. Les nagas aussi, soupçonnait-il.]=],
		},
	},
	mentions = {
		{ text = "Contre les Hatecrest" },
		{ text = "Contre le seigneur {link:lord-shalzaru}Shalzaru{/link}" },
		{ text = "La livraison de la relique" },
		{ text = "Le coursier disparu" },
		{ text = "La toile de Lethtendris" },
	},
	bonds = {
		{ id = "shandris-feathermoon", name = "Shandris Feathermoon", note = "sa générale" },
		{ id = "vestia-moonspear", name = "Vestia Moonspear", note = "sa femme" },
		{ id = "lord-shalzaru", name = "Seigneur Shalzaru", note = "ennemi" },
		{ id = "ginro-hearthkindle", name = "Ginro Hearthkindle", note = "un compagnon d'armes" },
	},
})

Translate("frFR", "vestia-moonspear", {
	title = "Vestia Moonspear",
	subtitle = "Prêtresse et érudite de Feathermoon",
	found = "Bastion de Feathermoon, parmi ses livres",
	hint = [=[Cherchez la prêtresse qui étudie dans un coin tranquille de Feathermoon.]=],
	allegiance = "Sentinelles · Bastion de Feathermoon",
	aliases = { "Vestia" },
	sections = {
		{
			title = "Résumé",
			text = [=[Vestia Moonspear est une prêtresse d'Elune et la femme de {link:latronicus-moonspear}Latronicus{/link}. Son mari la dit l'une des érudites les plus savantes qui soient, et il lui apporte toutes les énigmes qu'il ne sait pas résoudre. La plus grande d'entre elles est la relique prise au seigneur {link:lord-shalzaru}Shalzaru{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Vestia fut la première à dire tout haut ce que la relique pouvait signifier. Elle n'appartenait pas aux ruines d'où elle venait, et elle n'était pas de facture {link:naga}naga{/link}. C'était une chose plus étrange que l'une et l'autre.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle sert {link:feathermoon-stronghold}Feathermoon{/link} comme prêtresse.
• Elle a pris la relique {link:naga}naga{/link} pour l'étudier, et ne sait pas encore ce que c'est.]=],
		},
	},
	mentions = {
		{ text = "La livraison de la relique" },
	},
	bonds = {
		{ id = "latronicus-moonspear", name = "Latronicus Moonspear", note = "son mari" },
		{ id = "lord-shalzaru", name = "Seigneur Shalzaru", note = "a trouvé la relique qu'elle étudie" },
	},
})

Translate("frFR", "ginro-hearthkindle", {
	title = "Ginro Hearthkindle",
	subtitle = "Chercheur de Feathermoon",
	found = "Bastion de Feathermoon, dans ses quartiers",
	hint = [=[Trouvez la Sentinelle qui ne cesse de chercher un coursier disparu.]=],
	allegiance = "Sentinelles · Bastion de Feathermoon",
	aliases = { "Ginro", "Gin" },
	sections = {
		{
			title = "Résumé",
			text = [=[Ginro Hearthkindle est un soldat du {link:feathermoon-stronghold}Bastion de Feathermoon{/link} qui refusa d'abandonner un ami. Quand le coursier {link:raschal-the-courier}Raschal{/link} disparut sur la route de {link:thalanaar}Thalanaar{/link}, Ginro partit chaque jour dans les terres sauvages pour le retrouver, et revint chaque soir avec rien d'autre que des dents de {link:gnolls}gnoll{/link}. Même après que le bastion eut déclaré Raschal perdu, il continua de chercher.]=],
		},
		{
			title = "Importance",
			text = [=[Les recherches de Ginro mirent au jour le plus grave danger de {link:feralas}Féralas{/link}. En suivant la trace d'un coursier perdu, les chercheurs trouvèrent la ruche des Zukk'ash, premier signe en ces terres des silithides du sud.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il chercha {link:raschal-the-courier}Raschal{/link} jour après jour, seul.
• Il envoya le couteau du coursier au druide {link:quintis-jonespyre}Quintis Jonespyre{/link} pour qu'il le lise par le toucher, et paya ce service en effaçant une dette de jeu.
• Il plaida pour une attaque directe contre les camps Griffebois quand la vision du druide désigna ces lieux.
• Il présenta les sauveteurs de Raschal à {link:shandris-feathermoon}Shandris Feathermoon{/link}.]=],
		},
	},
	chapters = {
		{
			title = "L'épave",
			hint = [=[Fouillez la côte de Féralas à la recherche de la barque du coursier.]=],
			text = [=[{link:raschal-the-courier}Raschal{/link} comptait descendre la côte à la rame et traverser le sud de {link:feralas}Féralas{/link}, pour se tenir à l'écart du camp de la {link:horde}Horde{/link}. Sa barque fut retrouvée coulée et déchirée, l'emblème du bastion encore sur son flanc. Dans la vase, dessous, gisait son couteau. Quelque chose dans l'eau avait presque brisé la barque en deux.]=],
		},
		{
			title = "Ce que révèle le couteau",
			hint = "Découvrez ce dont se souvient le couteau du coursier.",
			text = [=[{link:quintis-jonespyre}Quintis{/link} tint le couteau et vit {link:raschal-the-courier}Raschal{/link} porter deux sacs à l'intérieur des terres, rencontrer les Griffebois, puis revenir à sa barque, effrayé. Raschal ne craignait rien de ce que les gnolls pouvaient faire. Autre chose l'avait effrayé, si fort qu'il ne vit jamais l'eau monter derrière lui. Ginro sut alors qu'il ne cherchait pas un cadavre.]=],
		},
		{
			title = "Libéré de la ruche",
			hint = "Suivez la piste du coursier jusqu'à son terme.",
			text = [=[Les sacs pendaient à un arbre dans les camps Griffebois. À l'intérieur se trouvait un mot : {link:raschal-the-courier}Raschal{/link} avait découvert des insectes au sud des gnolls et était parti les voir de ses propres yeux. Dans le {link:the-writhing-deep}Gouffre grouillant{/link}, on le retrouva scellé dans un cocon, étourdi mais vivant. Ginro dit à ses sauveteurs qu'ils auraient toujours en lui un ami.]=],
		},
	},
	mentions = {
		{ text = "Le coursier disparu" },
		{ text = "Les débris de la barque" },
		{ text = "Ce que révèle le couteau" },
		{ text = "Lecture psychométrique" },
		{ text = "Les gnolls Griffebois" },
		{ text = "{link:the-writhing-deep}Le Gouffre grouillant{/link}" },
		{ text = "Libéré de la ruche" },
		{ text = "L'accueil d'un héros" },
	},
	bonds = {
		{ id = "raschal-the-courier", name = "Raschal le coursier", note = "l'ami qu'il a cherché" },
		{ id = "quintis-jonespyre", name = "Quintis Jonespyre", note = "a lu le couteau, et lui doit une dette de jeu" },
		{ id = "latronicus-moonspear", name = "Latronicus Moonspear", note = "lui a envoyé de l'aide" },
		{ id = "shandris-feathermoon", name = "Shandris Feathermoon", note = "sa générale" },
	},
})

Translate("frFR", "raschal-the-courier", {
	title = "Raschal le coursier",
	subtitle = "Coursier de Feathermoon",
	found = "Un cocon dans le Gouffre grouillant",
	hint = "Suivez la piste du coursier disparu jusqu'à son terme.",
	allegiance = "Sentinelles · Bastion de Feathermoon",
	aliases = { "Raschal" },
	sections = {
		{
			title = "Résumé",
			text = [=[Raschal est le coursier qui porte les marchandises du {link:feathermoon-stronghold}Bastion de Feathermoon{/link} jusqu'à {link:thalanaar}Thalanaar{/link}. Il sert depuis que la générale a mené son peuple en {link:feralas}Féralas{/link}, et il connaît bien le pays. Lors de son dernier voyage, il rencontra les gnolls Griffebois, découvrit ce qui les tourmentait, et partit seul vers le sud pour en voir la cause.]=],
		},
		{
			title = "Importance",
			text = [=[Le rapport de Raschal sur les insectes du {link:the-writhing-deep}Gouffre grouillant{/link} fut envoyé à {link:darnassus}Darnassus{/link}, et une copie au {link:temple-of-the-moon}Temple de la Lune{/link}. Ce fut le premier avertissement de la présence des silithides en {link:feralas}Féralas{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il porta les colis du bastion par barque et à pied jusqu'à {link:thalanaar}Thalanaar{/link}.
• Il entra dans le {link:the-writhing-deep}Gouffre grouillant{/link} pour mesurer l'ampleur de la menace.
• Il fut submergé, scellé paralysé dans un cocon, et libéré vivant.]=],
		},
	},
	mentions = {
		{ text = "Libéré de la ruche" },
		{ text = "L'essor des silithides, son rapport" },
		{
			text = [=[Livraison pour {link:thalanaar}Thalanaar{/link}, son colis jamais livré]=],
		},
	},
	bonds = {
		{ id = "ginro-hearthkindle", name = "Ginro Hearthkindle", note = "n'a jamais cessé de le chercher" },
		{ id = "falfindel-waywarder", name = "Falfindel Waywarder", note = "attendait son colis" },
	},
})

Translate("frFR", "quintis-jonespyre", {
	title = "Quintis Jonespyre",
	subtitle = "Druide de Feathermoon",
	found = "Une maison perchée dans un arbre, au Bastion de Feathermoon",
	hint = "Montez jusqu'à la maison perchée du druide du bastion.",
	allegiance = "Cercle cénarien · Bastion de Feathermoon",
	aliases = { "Quintis" },
	sections = {
		{
			title = "Résumé",
			text = [=[Quintis Jonespyre est le druide résident du {link:feathermoon-stronghold}Bastion de Feathermoon{/link}, un serviteur de {link:malfurion-stormrage}Malfurion Stormrage{/link} et du {link:cenarion-circle}Cercle cénarien{/link}. Il vit dans une maison perchée dans un arbre, au-dessus de la garnison. Il étudie les malédictions, et il possède un don peu commun : en touchant un objet, il peut voir quelque chose de son passé.]=],
		},
		{
			title = "Importance",
			text = [=[Quintis ne fait pas confiance à l'archidruide. {link:fandral-staghelm}Fandral Staghelm{/link} amasse de grandes quantités de l'herbe appelée grain-du-matin au nom du Cercle, et Quintis a remarqué que le grain-du-matin se comporte comme les herbes employées dans les anciennes malédictions. Lui et ses collègues du Protectorat veulent savoir pourquoi.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il lut le couteau du coursier {link:raschal-the-courier}Raschal{/link} et vit ses dernières heures avant sa disparition.
• Il demande aux voyageurs qui récoltent du grain-du-matin pour {link:darnassus}Darnassus{/link} de lui en apporter discrètement.]=],
		},
	},
	mentions = {
		{ text = "La requête de Jonespyre" },
		{ text = "Le mystère du grain-du-matin" },
		{
			text = [=[Du grain-du-matin pour le {link:feathermoon-stronghold}Bastion de Feathermoon{/link}]=],
		},
		{ text = "Ce que révèle le couteau" },
		{ text = "Lecture psychométrique" },
	},
	bonds = {
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "l'archidruide dont il se méfie" },
		{ id = "ginro-hearthkindle", name = "Ginro Hearthkindle", note = "son partenaire de jeu" },
		{ id = "shandris-feathermoon", name = "Shandris Feathermoon", note = "du Protectorat" },
	},
})

Translate("frFR", "troyas-moonbreeze", {
	title = "Troyas Moonbreeze",
	subtitle = "Chercheur de ruines",
	found = "Bastion de Feathermoon, avec sa femme et leurs animaux",
	hint = [=[Parlez à l'érudit de Feathermoon qui fouille les vieilles ruines.]=],
	allegiance = "Bastion de Feathermoon",
	aliases = { "Troyas" },
	sections = {
		{
			title = "Résumé",
			text = [=[Troyas Moonbreeze et sa femme {link:angelas-moonbreeze}Angelas{/link} étudient les ruines qui parsèment {link:feralas}Féralas{/link}. Il croit que les pierres ont encore beaucoup à dire. Son collègue de {link:darnassus}Darnassus{/link} pense qu'il voit un trésor dans chaque tas de gravats. Depuis peu, il s'aventure seul dans les Plateaux sauvages, ce qui effraie sa femme.]=],
		},
		{
			title = "Importance",
			text = [=[Troyas eut raison au moins une fois. Un bâton qu'il trouva dans les ruines du sud se révéla être la clé du monolithe d'Equinex, et le monolithe s'ouvrit.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il trouva dans les ruines un bâton d'apparence ordinaire et refusa de s'en séparer.
• Il fit venir le livre {i}{link:feralas}Féralas{/link} : une histoire{/i} de la gardienne du savoir Daryn Lightwind.
• Il a commencé à étudier la Pierre de l'aube, tirée du monolithe.]=],
		},
	},
	chapters = {
		{
			title = "La Pierre de l'aube",
			hint = [=[Portez le bâton de l'érudit jusqu'au monolithe des ruines du nord.]=],
			text = [=[Chargé de l'essence de quatre anciennes flammes, le bâton devint trop lourd de puissance pour être tenu. À son contact, le monolithe d'Equinex ouvrit une petite porte, et à l'intérieur reposait une pierre scintillante. Troyas lut qu'elle se nommait la Pierre de l'aube. Il ne connaît pas son usage. Il sait seulement que nul ne cache une pierre ordinaire avec tant de soin.]=],
		},
	},
	mentions = {
		{ text = "En quête de savoir" },
		{ text = "Retour auprès de Troyas" },
		{ text = "Le bâton d'Equinex" },
		{ text = "La Pierre de l'aube" },
	},
	bonds = {
		{ id = "angelas-moonbreeze", name = "Angelas Moonbreeze", note = "sa femme" },
	},
})

