	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Rockbiter est un géant des collines du nord de {link:feralas}Féralas{/link}, et un géant doux. Il devait veiller sur {link:shay-leafrunner}Shay Leafrunner{/link}, une jeune {link:night-elves}elfe de la nuit{/link} qui vagabonde. Un instant, elle était à ses côtés dans les ruines au nord de son camp. L'instant d'après, elle avait disparu, et il ne savait plus que faire.]=],
		},
		{
			title = "Importance",
			text = [=[Dans une forêt où la plupart des géants sont dangereux, Rockbiter rappelle qu'ils ne le sont pas tous. Son amitié avec une petite elfe est l'un des récits les plus tendres de {link:feralas}Féralas{/link}.]=],
