			title = "Hauts faits",
			text = [=[• Il demanda à un voyageur de retrouver Shay, car de petites jambes sont plus rapides que les siennes.
• Il garde désormais sa clochette, pour pouvoir la rappeler.]=],
		},
	},
	mentions = {
		{ text = "Le géant gardien" },
		{ text = "Shay la vagabonde" },
	},
	bonds = {
		{ id = "shay-leafrunner", name = "Shay Leafrunner", note = "la fillette qu'il garde" },
	},
})

