Translate("frFR", "hadoken-swiftstrider", {
	title = "Hadoken Swiftstrider",
	subtitle = "Guerrier du camp Mojache",
	found = "Camp Mojache",
	hint = [=[Parlez au chef de guerre qui défend le camp Mojache contre les gnolls.]=],
	allegiance = "Horde · Camp Mojache",
	aliases = { "Hadoken" },
	sections = {
		{
			title = "Résumé",
			text = [=[Hadoken Swiftstrider commande la défense du camp {link:camp-mojache}Mojache{/link}. Il n'a aucune patience pour la question de savoir si les gnolls Griffebois ont leur place en {link:feralas}Féralas{/link}. Ils attaquent son camp, et si la {link:horde}Horde{/link} ne tient pas bon, elle sera chassée de la région. C'est un vétéran qui a lu bien des plans de bataille, et il reconnaît un ennemi désespéré quand il en voit un.]=],
		},
		{
			title = "Importance",
			text = [=[Hadoken fut le premier de la {link:horde}Horde{/link} à voir que les gnolls n'étaient pas la vraie menace. Il suivit leur peur vers le sud et trouva les Zukk'ash, et son rapport sur eux parvint à {link:orgrimmar}Orgrimmar{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il ordonna d'abattre les alphas Griffebois en succession rapide pour plonger les gnolls dans le chaos.
• Il envoya des hommes chercher les plans de bataille des gnolls.
• Il ordonna de décimer les Zukk'ash du {link:the-writhing-deep}Gouffre grouillant{/link}, et d'ouvrir leur plus grande bête, {link:stinglasher}Stinglasher{/link}, pour l'étudier.
• Il envoya le rapport du camp sur les insectes à Zilzibin Drumlore, à {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Guerre contre les Griffebois",
			hint = "Repoussez les gnolls qui attaquent le camp Mojache.",
			text = [=[Les Griffebois avaient toujours attaqué le camp, et la {link:horde}Horde{/link} les avait toujours repoussés. Depuis peu, les raids étaient devenus sauvages et incessants, comme si les gnolls n'avaient nulle part ailleurs où aller. Hadoken entendait les briser d'un seul coup sec. Cela fonctionna, un temps. Cela le fit aussi se demander ce qui les avait poussés à une telle frénésie.]=],
		},
		{
			title = "Les plans de bataille",
			hint = [=[Trouvez les plans de bataille des gnolls dans leurs camps du sud.]=],
			text = [=[La carte des gnolls racontait l'histoire. La plupart de leurs flèches pointaient vers le sud, loin du camp {link:camp-mojache}Mojache{/link}, et près du dessin d'un grand insecte s'alignaient des rangées de traits : leurs morts. Les Griffebois livraient une guerre sur deux fronts, et celle qu'ils perdaient n'était pas contre la {link:horde}Horde{/link}.]=],
		},
		{
			title = "Les Zukk'ash",
			hint = "Portez le rapport du camp sur les insectes à Orgrimmar.",
			text = [=[Peu importait à Hadoken que les insectes puissent penser. Ils repoussaient les gnolls vers son camp, et ils étaient donc ses ennemis. Quand ses découvertes parvinrent à Zilzibin Drumlore à {link:orgrimmar}Orgrimmar{/link}, le gobelin donna aux insectes leur vrai nom, silithides, et avertit que la {link:horde}Horde{/link} les avait ignorés bien trop longtemps.]=],
		},
	},
	mentions = {
		{ text = "Guerre contre les Griffebois" },
		{ text = "Frappe contre les alphas" },
		{ text = "Enquête sur les Griffebois" },
		{ text = "Les plans de bataille" },
		{ text = "Infestation de Zukk'ash" },
		{ text = "{link:stinglasher}Stinglasher{/link}" },
		{ text = "Rapport sur les Zukk'ash" },
	},
	bonds = {
		{ id = "stinglasher", name = "Stinglasher", note = "la bête qu'il voulait faire étudier" },
		{ id = "rok-orhan", name = "Rok Orhan", note = "combat les ogres à ses côtés" },
		{ id = "shandris-feathermoon", name = "Shandris Feathermoon", note = "tient le bastion de l'Alliance à l'ouest" },
	},
})

