})

Translate("frFR", "witch-doctor-uzer-i", {
	title = "Féticheur Uzer'i",
	subtitle = "Féticheur du camp Mojache",
	found = "Camp Mojache",
	hint = [=[Parlez au féticheur troll du camp Mojache qui cherche un réceptacle particulier.]=],
	allegiance = "Horde · Camp Mojache",
	aliases = { "Uzer'i" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le féticheur Uzer'i est un troll du camp {link:camp-mojache}Mojache{/link} et le maître d'un art ancien et inquiétant. Il connaît le muisek, l'esprit qu'une créature laisse derrière elle quand elle meurt par la violence. Un tel esprit, enseigne-t-il, peut s'échapper, chercher vengeance, et même revenir sous la forme d'une bête plus grande. Uzer'i a trouvé un moyen de l'en empêcher. Une créature rapetissée et capturée à l'instant de sa mort ne peut laisser partir son muisek, et un muisek capturé peut servir.]=],
		},
		{
			title = "Importance",
			text = [=[L'œuvre d'Uzer'i est une arme dirigée contre les elfes de la nuit. Il choisit ses créatures pour leur lien avec les {link:night-elves}kaldorei{/link} : les sélénides, jadis les familiers d'Elune ; les hippogriffes, leurs fidèles montures ; les dragons féeriques, leurs alliés ; les tréants, leurs protecteurs ; et les géants des montagnes, qui descendirent de leurs sommets pour les aider contre la {link:burning-legion}Légion ardente{/link}. Leur force, dit-il, devrait aussi servir la {link:horde}Horde{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il échangea la tête réduite d'un {link:dwarves}nain{/link} à {link:neeru-fireblade}Neeru Fireblade{/link} d'{link:orgrimmar}Orgrimmar{/link} contre les herbes dont son réceptacle avait besoin.
• Il envoya des chasseurs jusque dans {link:the-hinterlands}les Hinterlands{/link} capturer le muisek des sélénides.
• Il scella les esprits capturés dans des armes.]=],
		},
	},
	chapters = {
		{
			title = "Le réceptacle à muisek",
			hint = "Apportez au féticheur les herbes qu'il attend d'Orgrimmar.",
			text = [=[{link:neeru-fireblade}Neeru Fireblade{/link} avait préparé les herbes, et il fut satisfait de la tête qu'il reçut en échange. Uzer'i accomplit aussitôt son rituel sur le réceptacle. Sa première épreuve eut lieu très loin, parmi les chouettards des {link:the-hinterlands}Hinterlands{/link}, et elle devait mettre à l'épreuve à la fois le rituel et le chasseur qui portait le réceptacle.]=],
		},
		{
			title = "Les armes de l'esprit",
			hint = "Complétez la collection d'esprits du féticheur.",
			text = [=[Hippogriffe, dragon féerique, tréant et géant des montagnes : un à un, les alliés des elfes de la nuit furent rapetissés et capturés. Avec du bois éclaté, des minéraux, des tendons et des fragments de métal, Uzer'i lia leurs esprits pour toujours aux armes qu'il forgea.]=],
		},
	},
	mentions = {
		{ text = "Une étrange requête" },
		{ text = "Retour auprès du féticheur Uzer'i" },
		{ text = "L'essai du réceptacle" },
		{ text = "Le muisek de l'hippogriffe" },
		{ text = "Le muisek du dragon féerique" },
		{ text = "Le muisek du tréant" },
		{ text = "Le muisek du géant des montagnes" },
		{ text = "Matériaux naturels" },
		{ text = "Les armes de l'esprit" },
	},
	bonds = {
		{ id = "neeru-fireblade", name = "Neeru Fireblade", note = "échange des herbes avec lui" },
	},
})

Translate("frFR", "krueg-skullsplitter", {
	title = "Krueg Skullsplitter",
