Translate("frFR", "azj-tordin", {
	title = "Azj'Tordin",
	subtitle = "Ancien d'Eldre'Thalas",
	found = "Le Pavillon de Lariss",
	hint = [=[Cherchez l'ancien qui demeure parmi les ruines du Pavillon de Lariss.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Azj'Tordin est un ancien d'Eldre'Thalas qui a échappé à l'emprise de son prince déchu. Il a payé sa liberté de son immortalité, et il ne le regrette pas. Il vit désormais au {link:lariss-pavilion}Pavillon de Lariss{/link}, parmi de vieilles pierres dans la forêt de l'est.]=],
		},
		{
			title = "Importance",
