			title = "Résumé",
			text = [=[Le sage Korolusk a suivi une longue piste jusqu'en {link:feralas}Féralas{/link}. Il cherche Kariel Winthalus, un maître elfe qui a fui la dévastation de sa patrie avec d'anciens artefacts elfiques. La piste mena des ruines de {link:quel-thalas}Quel'Thalas{/link} aux {link:burning-steppes}Steppes ardentes{/link}, puis au-delà de la mer, et elle s'achève, croit Korolusk, dans les salles d'Eldre'Thalas.]=],
		},
		{
			title = "Importance",
			text = [=[Korolusk et l'érudit {link:scholar-runethorn}Runethorn{/link} de {link:feathermoon-stronghold}Feathermoon{/link} traquent le même homme pour le même savoir, l'un pour la {link:horde}Horde{/link} et l'autre pour l'{link:alliance}Alliance{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il demande que Hache-tripes soit fouillé à la recherche de Kariel, vivant ou mort.]=],
		},
	},
	mentions = {
		{ text = "Légendes elfiques" },
	},
	bonds = {
		{ id = "scholar-runethorn", name = "Érudit Runethorn", note = "cherche le même maître" },
	},
})

