Translate("frFR", "falfindel-waywarder", {
	title = "Falfindel Waywarder",
	subtitle = "Druide de Thalanaar",
	found = "Thalanaar, à la lisière est de Féralas",
	hint = [=[Cherchez le druide qui tient le relais à la lisière est de la forêt.]=],
	allegiance = "Cercle cénarien · Thalanaar",
	aliases = { "Falfindel" },
	sections = {
		{
			title = "Résumé",
			text = [=[Falfindel Waywarder est un druide des elfes de la nuit qui tient {link:thalanaar}Thalanaar{/link}, le relais solitaire où les forêts de {link:feralas}Féralas{/link} rejoignent les canyons de {link:thousand-needles}Mille pointes{/link}. Les gardiens des {link:stonetalon-mountains}Serres-Rocheuses{/link} le disent grand et sage. On raconte qu'il peut appeler les grands esprits de la forêt au secours des terres blessées.]=],
		},
		{
			title = "Importance",
			text = [=[Depuis son poste tranquille, Falfindel veille sur bien plus que {link:feralas}Féralas{/link}. Son souci s'étend jusqu'aux {link:the-barrens}Tarides{/link}, où le lieu de repos du demi-dieu sanglier Agamaggan a été corrompu, et jusqu'aux {link:stonetalon-mountains}Serres-Rocheuses{/link} au nord, dont le gardien a imploré son aide.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il étudie ce qui a corrompu le lieu de repos d'Agamaggan, dans le sud des {link:the-barrens}Tarides{/link}.
• Il envoya d'autres combattre la mégère {link:charlga-razorflank}Charlga Razorflank{/link} du {link:razorfen-kraul}Kraal de Tranchebauge{/link}.
• Il répond à la supplique du {link:keeper-albagorm}gardien Albagorm{/link} en envoyant des esprits de la forêt dans le {link:the-charred-vale}Val calciné{/link}.
• Il attend les provisions que des coursiers portent de {link:feathermoon-stronghold}Feathermoon{/link} à travers {link:feralas}Féralas{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La mégère du Kraal",
			hint = "Portez le journal d'un nain mort jusqu'à Thalanaar.",
			text = [=[Le journal d'Henrig Lonebrow apprit à Falfindel la capture du druide {link:heralath-fallowbrook}Heralath{/link} dans {link:razorfen-kraul}le Kraal{/link}, et l'existence d'une mégère qui devenait plus forte de jour en jour. Il n'y avait pas le temps de demander de l'aide à {link:darnassus}Darnassus{/link}. Quand le médaillon de la mégère lui revint, il osa espérer que ses études pourraient se poursuivre, bien qu'il craignît que leur réponse ne soit une trahison.]=],
		},
		{
			title = "Un appel des Serres-Rocheuses",
			hint = [=[Portez la supplique du gardien Albagorm au druide de Thalanaar.]=],
			text = [=[Les harpies du {link:the-charred-vale}Val calciné{/link} avaient été brisées, mais elles reviendraient, et des graines seules ne pouvaient guérir le val avant leur retour. {link:keeper-albagorm}Albagorm{/link} envoya un message à Falfindel, à l'autre bout de la moitié de {link:kalimdor}Kalimdor{/link}. Le druide ne perdit pas de mots. Il se tourna aussitôt vers la grande forêt pour appeler du secours.]=],
		},
		{
			title = "Le colis en retard",
			hint = "Apportez à Thalanaar le colis perdu du coursier.",
			text = [=[Le colis de {link:feathermoon-stronghold}Feathermoon{/link} arriva en retard, et de la main d'un étranger. Falfindel devina aussitôt qu'il était arrivé quelque chose à {link:raschal-the-courier}Raschal{/link}, le coursier habituel. Il avait ses propres soupçons : les Griffebois s'agitaient depuis peu, troublés par quelque chose venu du sud.]=],
		},
	},
	mentions = {
		{ text = "Le journal de Lonebrow" },
		{ text = "La mégère du {link:razorfen-kraul}Kraal{/link}" },
		{
			text = [=[Reconquérir le {link:the-charred-vale}Val calciné{/link}, la supplique des {link:stonetalon-mountains}Serres-Rocheuses{/link}]=],
		},
		{ text = "Livraison pour {link:thalanaar}Thalanaar{/link}" },
	},
	bonds = {
		{ id = "keeper-albagorm", name = "Gardien Albagorm", note = "a demandé son aide" },
		{ id = "heralath-fallowbrook", name = "Heralath Fallowbrook", note = "le druide capturé dans le Kraal" },
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "ennemie" },
		{ id = "raschal-the-courier", name = "Raschal le coursier", note = "son coursier habituel" },
	},
})

Translate("frFR", "zorbin-fandazzle", {
	title = "Zorbin Fandazzle",
	subtitle = "Ingénieur gobelin de la Côte oubliée",
	found = "Près du quai de la Côte oubliée",
