• Il l'alimente avec les noyaux des élémentaires de la mer de la côte.
• Il dit du bien, à qui veut l'entendre, de ceux qui l'aident.]=],
		},
	},
	mentions = {
		{ text = "Géants rétrécis" },
		{ text = "Encore des géants rétrécis" },
		{ text = "Du carburant pour le rayon" },
		{ text = "Refaire le plein du rayon" },
	},
	bonds = {
		{ id = "rockbiter", name = "Rockbiter", note = "l'un des géants qu'il préférerait rapetisser" },
	},
})

Translate("frFR", "gregan-brewspewer", {
