	subtitle = "Dragon vert du Bosquet du rêve",
	found = "Le Bosquet du rêve",
	hint = [=[Approchez, avec une grande prudence, le dragon vert qui garde le Bosquet du rêve.]=],
	allegiance = "Vol vert",
	sections = {
		{
			title = "Résumé",
			text = [=[Lethlas est un grand dragon vert qui garde le {link:dream-bough}Bosquet du rêve{/link}, au nord de {link:feralas}Féralas{/link}. Avec un autre de son espèce, Dreamroarer, et les draconiens du Lac Jademir, il protège l'arbre et sa porte vers le {link:emerald-dream}Rêve d'émeraude{/link} de tous ceux qui s'approchent.]=],
		},
		{
