			text = [=[Lethlas est le signe que le {link:dream-bough}Bosquet du rêve{/link} n'est pas un simple bosquet, mais un lieu cher aux dragons verts.]=],
		},
		{ title = "Hauts faits", text = "• Il garde le {link:dream-bough}Bosquet du rêve{/link}." },
		{
			title = "Non consigné",
			text = [=[Aucun récit recueilli à ce jour en {link:feralas}Féralas{/link} ne parle de l'âge de Lethlas, de ses paroles ou de son service avant sa venue au Bosquet.]=],
		},
	},
	bonds = {
		{ id = "dream-bough", name = "Bosquet du rêve", note = "l'arbre qu'il garde" },
	},
})
